# 032 - la tonalita' funziona anche sulle basi prese da internet.
#
# Con una base online l'audio da trasporre si estrae con ffmpeg in un file
# temporaneo, il cui nome veniva ricavato dall'indirizzo. Ma l'indirizzo di
# YouTube e' lungo oltre mille caratteri e contiene '?': ne usciva un nome di
# file impossibile, la creazione falliva e - senza dire niente - la tonalita'
# non si muoveva piu'.
#
# SE NON VA BENE: `patch_032 = 0` la spegne su una macchina sola.

CODICE = 'def _extract_video_audio(self, video_path):\n    """Estrai traccia audio da un video → temp WAV per Pedalboard pitch shift."""\n    import tempfile\n    temp_dir = tempfile.gettempdir()\n\n    # ⛔ SE ARRIVA UN INDIRIZZO, IL NOME NON SI RICAVA DALL\'INDIRIZZO.\n    #    Le basi online passano di qui con l\'indirizzo diretto di YouTube:\n    #    1145 caratteri con dentro \'?\' e \'&\'. Con basename() ne usciva un\n    #    nome di 603 caratteri, col \'?\' che Windows non ammette e oltre il\n    #    limite dei 260: la creazione falliva con "Invalid argument",\n    #    ffmpeg non estraeva niente, BASS restava senza audio e la\n    #    tonalita\' non funzionava — tutto in silenzio, senza un errore\n    #    visibile. Con un indirizzo si usa un\'impronta corta: nome sempre\n    #    valido, e sempre lo STESSO per lo stesso brano, cosi\' la seconda\n    #    volta l\'audio gia\' estratto si riusa invece di rifarlo.\n    _e_indirizzo = str(video_path).lower().startswith((\'http://\', \'https://\'))\n    if _e_indirizzo:\n        import hashlib\n        import re as _re\n        # dell\'indirizzo si tiene solo la parte stabile: cambiando la\n        # scadenza (expire=...) il brano e\' sempre quello\n        _chiave = _re.sub(r\'[?&](expire|ei|ip|met|mh|mm|mn|ms|rms|initcwndbps|\'\n                          r\'bui|spc|sig|lsig|pcm2cms)=[^&]*\', \'\', str(video_path))\n        base = \'yt_\' + hashlib.sha1(_chiave.encode(\'utf-8\', \'replace\')).hexdigest()[:16]\n    else:\n        base = os.path.splitext(os.path.basename(video_path))[0]\n    output = os.path.join(temp_dir, f"{base}_extracted_audio.wav")\n    \n    if os.path.exists(output) and os.path.getsize(output) > 1000:\n        print(f"🎬 Audio video cache: {output}")\n        return output\n    \n    # Estrai audio con ffmpeg\n    # ⚠️ IL PERCORSO VA CERCATO, non si scrive \'ffmpeg\' e basta: sui PC dei\n    # clienti ffmpeg NON e\' nel PATH di sistema (sta in dipendenze\\, spedito\n    # con il programma). Chiamandolo nudo l\'estrazione falliva in silenzio,\n    # l\'audio non arrivava a BASS e la tonalita\' sui video non funzionava:\n    # si ricadeva sulla velocita\' e il video rallentava.\n    try:\n        import subprocess\n        # ⚠️ Nel COMPILATO la cartella non si ricava da __file__ (Nuitka lo\n        # mette altrove): si parte da sys.argv[0], come fa gia\' yt2mp3.\n        ffmpeg = \'ffmpeg\'\n        try:\n            from .yt2mp3 import _dep as _dip\n            _f = _dip(\'ffmpeg.exe\' if os.name == \'nt\' else \'ffmpeg\')\n            if os.path.exists(_f):\n                ffmpeg = _f\n            else:\n                from .normalizzazione import _get_ffmpeg_path\n                ffmpeg = _get_ffmpeg_path()\n        except Exception:\n            pass\n        print(f"🎬 Estrazione audio da: {Path(video_path).name} (con {ffmpeg})...")\n        subprocess.run([ffmpeg, \'-y\', \'-i\', video_path, \'-vn\', \'-acodec\', \'pcm_s24le\',\n                       \'-ar\', \'48000\', \'-ac\', \'2\', output],\n                      capture_output=True, timeout=120,\n                      creationflags=0x08000000 if os.name == \'nt\' else 0)\n        if os.path.exists(output) and os.path.getsize(output) > 1000:\n            print(f"🎬 Estratto con ffmpeg: {os.path.getsize(output)/(1024*1024):.1f}MB")\n            return output\n    except Exception as e:\n        print(f"⚠️ ffmpeg: {e}")\n    \n    return None'

CODICE_LIB = 'def play_brano(self, path, entry_ton=None, cantante="", brano="", tonalita=None):\n\n    """Riproduce brano con tonalità dalla riga E aggiorna info centrale"""\n\n    # ✅ Intercetta link YouTube — estrazione robusta video_id\n    import re as _re\n    from urllib.parse import urlparse, parse_qs\n    \n    check_str = str(path or \'\') + \' \' + str(brano or \'\')\n    dbg("LIBRERIA", f" path={repr(path)[:100]} brano={repr(brano)[:100]}")\n    video_id = None\n    \n    # Metodo 1: Regex standard\n    yt_match = _re.search(r\'(?:youtube\\.com/watch\\?v=|youtu\\.be/|youtube\\.com/embed/|youtube\\.com/shorts/)([a-zA-Z0-9_-]{11})\', check_str, _re.IGNORECASE)\n    if yt_match:\n        video_id = yt_match.group(1)\n    \n    # Metodo 2: Fallback con urllib.parse (gestisce parametri extra, encoding, etc.)\n    if not video_id:\n        for s in [str(path or \'\'), str(brano or \'\')]:\n            s = s.strip()\n            if \'youtu\' not in s.lower():\n                continue\n            try:\n                parsed = urlparse(s if \'://\' in s else \'https://\' + s)\n                if \'youtu.be\' in parsed.hostname:\n                    # youtu.be/VIDEO_ID\n                    vid = parsed.path.lstrip(\'/\')\n                    if len(vid) >= 11:\n                        video_id = vid[:11]\n                elif \'youtube.com\' in parsed.hostname:\n                    # youtube.com/watch?v=VIDEO_ID\n                    qs = parse_qs(parsed.query)\n                    if \'v\' in qs and len(qs[\'v\'][0]) == 11:\n                        video_id = qs[\'v\'][0]\n            except:\n                pass\n            if video_id:\n                break\n    \n    if video_id and len(video_id) == 11:\n        dbg("LIBRERIA", f" YouTube ID estratto: {video_id}")\n\n        # Il video YouTube va riprodotto COME UN VIDEO NORMALE (VLC, su\n        # principale + pubblico), non in una finestra Chromium: yt-dlp lo\n        # scarica e si passa a load_file. Se fallisce si ripiega sul browser.\n        # Per tornare al vecchio comportamento: YT_COME_VIDEO = False.\n        YT_COME_VIDEO = True\n\n        def _apri_browser():\n            if not hasattr(self.system, \'youtube_browser\') or self.system.youtube_browser is None:\n                from .youtube_browser import YouTubeWebViewBrowser\n                self.system.youtube_browser = YouTubeWebViewBrowser(self.parent, self.system)\n            self.system.youtube_browser.play_video(video_id)\n\n        if YT_COME_VIDEO:\n            try:\n                from .youtube_local import riproduci_youtube\n                riproduci_youtube(self.system, self.parent, video_id,\n                                  tonalita=(tonalita or 0),\n                                  ripiego_browser=_apri_browser)\n            except Exception as _e:\n                print(f"[YT-STREAM] non disponibile ({_e}) -> browser")\n                _apri_browser()\n        else:\n            _apri_browser()\n\n        # ✅ APPLICA PITCH dalla riga della libreria (non-bloccante)\n        try:\n            if tonalita is not None:\n                yt_pitch = tonalita\n            elif entry_ton:\n                try:\n                    yt_pitch = int(entry_ton.get().strip() or "0")\n                except:\n                    yt_pitch = 0\n            else:\n                yt_pitch = self.pitch_var.get() if self.pitch_var else 0\n            \n            if yt_pitch != 0:\n                self.system.current_pitch = yt_pitch\n                if self.pitch_var is not None:\n                    self.pitch_var.set(yt_pitch)\n                if self.pitch_label_ref and self.pitch_label_ref[\'label\']:\n                    self.pitch_label_ref[\'label\'].config(text=f"{yt_pitch:+d}")\n                # ⛔ LA TONALITA\' SI DA\' AL PROGRAMMA, NON AL BROWSER.\n                #    Qui si chiamava `youtube_browser.set_pitch`, ma quel\n                #    browser esiste solo nel vecchio percorso: da quando le\n                #    basi online si riproducono come un video normale\n                #    (YT_COME_VIDEO) non viene piu\' creato, e la chiamata\n                #    moriva con "no attribute \'youtube_browser\'" un secondo\n                #    e mezzo dopo la partenza. Risultato: sulle basi prese\n                #    da internet la tonalita\' non arrivava a destinazione.\n                #    `system.set_pitch` sceglie da se\' il motore giusto -\n                #    e avvisa il browser solo se c\'e\' davvero.\n                _p = yt_pitch\n\n                def _dai_la_tonalita(_p=_p):\n                    try:\n                        self.system.set_pitch(_p)\n                    except Exception as e:\n                        print(f"⚠️ tonalita\' base online: {e}")\n\n                self.parent.after(1500, _dai_la_tonalita)\n                print(f"🎵 YouTube pitch dalla riga: {yt_pitch:+d}")\n        except Exception as e:\n            print(f"⚠️ YouTube pitch errore: {e}")\n\n        if self.info_brano_ref:\n\n            if self.info_brano_ref.get(\'cantante\'):\n\n                self.info_brano_ref[\'cantante\'].config(text=cantante.upper() if cantante else "---")\n\n            if self.info_brano_ref.get(\'brano\'):\n\n                self.info_brano_ref[\'brano\'].config(text=brano.upper() if brano else video_id)\n\n            if self.info_brano_ref.get(\'ext\'):\n\n                self.info_brano_ref[\'ext\'].config(text="[YT]")\n\n        print(f"▶ YouTube: {cantante} - {brano} [{video_id}]")\n        \n        # ✅ Chiudi libreria automaticamente dopo play YouTube\n        if self.slider_visible:\n            self.toggle_slider()\n\n        try:\n\n            from .history import log_brano\n\n            log_brano(f"YT:{brano or video_id}", cantante)\n\n        except Exception:\n\n            pass\n\n        return\n\n\n\n    # ✅ BASI ONLINE (KDM): il brano non e\' un file locale ma sta sul db online.\n    #    path = \'kdmonline://<sorgente:rowid>\'. Lo scarichiamo PRIMA in un file\n    #    temporaneo, poi proseguiamo col normale flusso di riproduzione locale.\n    if isinstance(path, str) and path.startswith(\'kdmonline://\'):\n        db_id = path[len(\'kdmonline://\'):]\n        try:\n            import tempfile\n            from .basi_online import scarica, is_video\n            suffix = \'.mp4\' if is_video(db_id) else \'.mp3\'\n            fd, temp_path = tempfile.mkstemp(suffix=suffix, prefix=\'kdm_\')\n            os.close(fd)\n            dbg("LIBRERIA", f" Download online {db_id} -> {temp_path}")\n            res = scarica(db_id, temp_path)\n        except Exception as e:\n            dbg("LIBRERIA", f" ❌ Errore download online: {e}")\n            res = None\n        if not res:\n            messagebox.showerror(_("Errore"), _("Impossibile scaricare il brano online.\\nVerifica la connessione o la licenza."), parent=self.parent)\n            return\n        path = res\n        dbg("LIBRERIA", f" Brano online pronto: {path}")\n\n    if path and os.path.exists(path):\n        dbg("LIBRERIA", f" File trovato: {path}")\n        # Prendi tonalità: prima da parametro diretto, poi da entry_ton, infine mantieni corrente\n\n        if tonalita is not None:\n\n            # Tonalità specificata esplicitamente\n\n            pass\n\n        elif entry_ton:\n\n            # Prendi da campo entry\n\n            try:\n\n                tonalita = int(entry_ton.get().strip() or "0")\n\n            except:\n\n                tonalita = 0\n\n        else:\n\n            # ✅ MANTIENI PITCH CORRENTE se non specificato\n\n            tonalita = self.pitch_var.get() if self.pitch_var else 0\n\n        \n\n        # AGGIORNA controlli pitch in basso\n\n        if self.pitch_var is not None:\n\n            self.pitch_var.set(tonalita)\n\n        if self.pitch_label_ref and self.pitch_label_ref[\'label\']:\n\n            if tonalita == 0:\n\n                self.pitch_label_ref[\'label\'].config(text="0")\n\n            else:\n\n                self.pitch_label_ref[\'label\'].config(text=f"{tonalita:+d}")\n\n        \n\n        # AGGIORNA INFO BRANO CENTRALE (cantante e brano separati)\n\n        if self.info_brano_ref:\n\n            if self.info_brano_ref.get(\'cantante\'):\n\n                self.info_brano_ref[\'cantante\'].config(text=cantante if cantante else "---")\n\n            if self.info_brano_ref.get(\'brano\'):\n\n                self.info_brano_ref[\'brano\'].config(text=brano if brano else "---")\n\n            if self.info_brano_ref.get(\'ext\'):\n\n                ext = Path(path).suffix[1:].upper()\n\n                self.info_brano_ref[\'ext\'].config(text=ext)\n\n        \n\n        print(f"▶ Caricamento: {os.path.basename(path)} (Ton: {tonalita:+d})")\n\n        \n        # ✅ Se è lo STESSO FILE già in riproduzione → swap senza riavvolgimento\n        same_file = (self.system.current_file and \n                    os.path.normpath(self.system.current_file) == os.path.normpath(path))\n        \n        if same_file and self.system.is_playing and tonalita == getattr(self.system, \'current_pitch\', 0):\n            # Stesso file, stesso pitch → restart istantaneo\n            self.system.restart()\n            print(f"▶ {os.path.basename(path)}")\n            \n            # ✅ Chiudi libreria automaticamente dopo play\n            if self.slider_visible:\n                self.toggle_slider()\n        elif self.system.load_file(path, tonalita):\n\n            # ✅ AGGIORNA DURATA nei controlli in basso\n\n            if self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n\n                if self.system.engine and self.system.engine.total_duration_ms > 0:\n\n                    total_sec = int(self.system.engine.total_duration_ms / 1000)\n\n                    self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n\n                elif self.system.monitor.syllables_data:\n\n                    total_ms = self.system.monitor.syllables_data[-1][1]\n\n                    total_sec = int(total_ms / 1000)\n\n                    self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n\n            \n\n            # Play con tonalità\n\n            self.system.play(tonalita)\n\n            print(f"▶ {os.path.basename(path)}")\n            \n            # ✅ Chiudi libreria automaticamente dopo play\n            if self.slider_visible:\n                self.toggle_slider()\n\n            \n\n# ✅ AGGIORNA MIXER se è un file MIDI\n\n            if path.lower().endswith((\'.mid\', \'.kar\', \'.midi\')):\n\n                from .mixer import MIDIMixerPanel\n\n                mixer = MIDIMixerPanel.get_instance()\n\n                \n\n                if not mixer:\n\n                    # Crea il mixer (rimane chiuso)\n\n                    mixer = MIDIMixerPanel(self.parent, self.system)\n\n                    print("🎚️ Libreria: Mixer creato automaticamente")\n\n                \n\n                # Melody muted: sempre True per default\n\n                melody_is_muted = True\n\n                \n\n                mixer.load_midi_file(path, melody_muted=melody_is_muted)\n\n                print(f"🎚️ Libreria: Chiamato mixer.load_midi_file({os.path.basename(path)})")\n\n            \n\n            # ✅ Log brano nella history SIAE\n\n            try:\n\n                from .history import log_brano\n\n                titolo = Path(path).stem\n\n                log_brano(titolo)\n\n            except Exception as e:\n\n                print(f"⚠️ Errore log history: {e}")\n\n        else:\n\n            # ✅ Mostra errore dettagliato per diagnostica\n            errore_dettaglio = getattr(self.system, \'last_error\', \'\') or \'Errore sconosciuto\'\n            messagebox.showerror(_("Errore"), _("Impossibile caricare:\\n{path}\\n\\nDettaglio: {errore_dettaglio}").format(path=path, errore_dettaglio=errore_dettaglio), parent=self.parent)\n\n    else:\n        # ✅ Se è un URL YouTube che non è stato intercettato, non mostrare "File non trovato"\n        _path_str = str(path or \'\').lower()\n        if \'youtu.be/\' in _path_str or \'youtube.com/\' in _path_str:\n            dbg("LIBRERIA", f" ❌ URL YouTube non intercettato! path={path}")\n            messagebox.showerror(_("Errore"), _("Impossibile estrarre Video ID da:\\n{path}\\n\\nFormati supportati:\\nhttps://youtu.be/XXXXXXXXXXX\\nhttps://www.youtube.com/watch?v=XXXXXXXXXXX").format(path=path), parent=self.parent)\n        else:\n            dbg("LIBRERIA", f" ❌ File non trovato! path={repr(path)}")\n            messagebox.showerror(_("Errore"), _("File non trovato!"), parent=self.parent)'


def _spenta():
    try:
        from moduli.database import Database
        if str(Database.get_config('patch_032', '1')).strip() in ('0', 'no', 'off'):
            traccia('spenta a mano (patch_032 = 0)')
            return True
    except Exception:
        pass          # la configurazione non risponde: non e' un motivo per spegnersi
    return False


def traccia(testo):
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch032.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                testo) + chr(10))
    except Exception:
        pass


def apply():
    if _spenta():
        traccia('non mi accendo (vedi la riga qui sopra)')
        return False
    try:
        import moduli.system as m
        C = m.KaraokeMonitorSystem
        if hasattr(C, '_orig_032'):
            traccia('gia' + chr(39) + ' agganciata')
            return True
        C._orig_032 = C._extract_video_audio
        spazio = m.__dict__
        exec(compile(CODICE, "<patch032>", "exec"), spazio)
        setattr(C, '_extract_video_audio', spazio['_extract_video_audio'])
        traccia('AGGANCIATA: audio estraibile anche da un indirizzo')

        # ⭐ seconda meta': la tonalita' va data al programma, non a un
        #    browser che oggi non viene piu' creato
        try:
            import moduli.libreria as ml
            spazio_l = ml.__dict__
            exec(compile(CODICE_LIB, "<patch032lib>", "exec"), spazio_l)
            setattr(ml.LibreriaSlider, 'play_brano', spazio_l['play_brano'])
            traccia('AGGANCIATA: la tonalita non passa piu dal browser')
        except Exception as e:
            traccia('libreria NON agganciata: %s: %s' % (type(e).__name__, e))
        print("patch 032: tonalita' anche sulle basi online")
        return True
    except Exception as e:
        traccia('NON agganciata: %s: %s' % (type(e).__name__, e))
        print("patch 032: %s" % e)
        return False


def revert():
    try:
        import sys
        m = sys.modules.get('moduli.system')
        C = getattr(m, 'KaraokeMonitorSystem', None) if m else None
        if C is not None and hasattr(C, '_orig_032'):
            setattr(C, '_extract_video_audio', C._orig_032)
            del C._orig_032
            print("patch 032: rimesso l'originale")
            return True
    except Exception as e:
        print("patch 032: %s" % e)
    return False


try:
    apply()
except Exception:
    pass
